        raise TypeError("text must be a string")

    if not text:
        raise ValueError("empty string")

    if ' ' in text:
        raise ValueError("whitespace not allowed")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    expected_order = ['d', 'h', 'm', 's']
    seen_units = set()
    total_seconds = 0
    current_num_str = ""

    i = 0
    while i < len(text):
        char = text[i]

        if char.isdigit():
            current_num_str += char
        elif char in units:
            if not current_num_str:
                raise ValueError("unit without number")

            unit = char
            if unit in seen_units:
                raise ValueError("repeated unit")

            if unit != expected_order[seen_units | {unit} - seen_units if seen_units else 0]:
                # Check if the unit is in the correct position relative to already seen units
                current_idx = expected_order.index(unit) if unit in expected_order else -1
                for seen_unit in seen_units:
                    seen_idx = expected_order.index(seen_unit)
                    if seen_idx > current_idx:
                        raise ValueError("out-of-order units")

            if unit not in expected_order:
                raise ValueError("unknown unit")

            num = int(current_num_str)
            total_seconds += num * units[unit]
            seen_units.add(unit)
            current_num_str = ""
        else:
            raise ValueError(f"invalid character: {char}")

        i += 1

    if current_num_str:
        raise ValueError("number without unit")

    return total_seconds
