def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("weights must not be all zero")

    total_weight = sum(weights)
    base_amounts = [total * w // total_weight for w in weights]
    remainder = total - sum(base_amounts)

    if remainder > 0:
        fractional_parts = [(total * w) % total_weight for w in weights]
        indices = list(range(len(weights)))
        indices.sort(key=lambda i: (-fractional_parts[i], i))
        for i in range(remainder):
            base_amounts[indices[i]] += 1

    return base_amounts
