function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',').filter(p => p.trim() !== '');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part');
    }

    if (trimmed.includes('+') || trimmed.includes('.') || /[a-zA-Z]/.test(trimmed)) {
      throw new SyntaxError('Invalid character in part');
    }

    const dashIndex = trimmed.indexOf('-');
    if (dashIndex === -1) {
      const num = parseInt(trimmed, 10);
      if (isNaN(num) || num < 0) {
        throw new SyntaxError('Invalid number');
      }
      result.add(num);
    } else if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
      throw new SyntaxError('Missing start or end in range');
    } else if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
      throw new SyntaxError('More than one dash');
    } else {
      const [loStr, hiStr] = trimmed.split('-');
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi) || lo < 0 || hi < 0) {
        throw new SyntaxError('Invalid number in range');
      }

      if (lo > hi) {
        throw new RangeError('Start of range must not exceed end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

