def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Loop completed without break -> unclosed quote
                raise ValueError("Quoted field is never closed")

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Invalid character after closing quote")

            fields.append(''.join(field_chars))
        else:
            # Unquoted field
            field_chars = []
            while i < n and line[i] != ',':
                field_chars.append(line[i])
                i += 1
            fields.append(''.join(field_chars))
            # If we stopped because of comma, the next iteration will handle it
            # If we stopped because i == n, we are done with this field and the line
            if i < n and line[i] == ',':
                i += 1

    return fields
