import re

def compare_versions(a, b):
    def parse_version(s):
        if not s:
            raise ValueError("Empty version string")

        # Split into major.minor.patch and optional prerelease/build
        # Regex to validate the structure
        pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?(?:\+([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?$'
        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version format: {s}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))

        prerelease_str = match.group(4)
        build_str = match.group(5)

        # Validate prerelease identifiers if present
        if prerelease_str:
            if not prerelease_str:
                raise ValueError("Empty prerelease")
            identifiers = prerelease_str.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError("Empty identifier in prerelease")
                # Check if all digits and has leading zero
                if ident.isdigit():
                    if len(ident) > 1 and ident[0] == '0':
                        raise ValueError(f"Leading zero in numeric prerelease identifier: {ident}")

        # Validate build identifiers if present
        if build_str:
            if not build_str:
                raise ValueError("Empty build metadata")
            identifiers = build_str.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError("Empty identifier in build metadata")

        return {
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': prerelease_str,
            'build': build_str
        }

    v1 = parse_version(a)
    v2 = parse_version(b)

    # Compare major, minor, patch
    if v1['major'] != v2['major']:
        return -1 if v1['major'] < v2['major'] else 1
    if v1['minor'] != v2['minor']:
        return -1 if v1['minor'] < v2['minor'] else 1
    if v1['patch'] != v2['patch']:
        return -1 if v1['patch'] < v2['patch'] else 1

    # Compare prerelease
    # No prerelease > prerelease
    if v1['prerelease'] is None and v2['prerelease'] is None:
        return 0
    if v1['prerelease'] is None:
        return 1
    if v2['prerelease'] is None:
        return -1

    # Both have prerelease, compare identifiers
    ids1 = v1['prerelease'].split('.')
    ids2 = v2['prerelease'].split('.')

    for i in range(max(len(ids1), len(ids2))):
        if i >= len(ids1):
            return -1 # v1 has fewer identifiers
        if i >= len(ids2):
            return 1  # v2 has fewer identifiers

        id1 = ids1[i]
        id2 = ids2[i]

        # Check if identifiers are numeric
        is_num1 = id1.isdigit()
        is_num2 = id2.isdigit()

        if is_num1 and is_num2:
            # Compare numerically
            if int(id1) != int(id2):
                return -1 if int(id1) < int(id2) else 1
        elif is_num1:
            # Numeric < Alphanumeric
            return -1
        elif is_num2:
            # Alphanumeric > Numeric
            return 1
        else:
            # Both alphanumeric, compare lexically
            if id1 != id2:
                return -1 if id1 < id2 else 1

    return 0
