function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  for (const row of rows) {
    if (!Array.isArray(row)) {
      throw new TypeError('each row must be an array');
    }
  }

  const cellToString = (cell) => {
    if (cell == null) return '';
    return String(cell);
  };

  const processedRows = rows.map((row) =>
    row.map(cellToString)
  );

  const colWidths = processedRows.reduce((widths, row) => {
    for (let i = 0; i < row.length; i++) {
      const width = row[i].length;
      if (i >= widths.length || width > widths[i]) {
        widths[i] = width;
      }
    }
    return widths;
  }, []);

  const maxCols = Math.max(0, ...processedRows.map((r) => r.length));
  const finalColWidths = Array.from({ length: maxCols }, (_, i) =>
    i < colWidths.length ? colWidths[i] : 0
  );

  const lines = processedRows.map((row) => {
    const paddedCells = row.map((cell, i) => {
      const width = finalColWidths[i];
      const str = String(cell);
      return str.padEnd(width, ' ');
    });

    const joined = paddedCells.join(' | ');
    return joined.trimEnd();
  });

  return lines.join('\n');
}

