        if char == '"':
            # Parse string literal
            i += 1
            while i < n:
                if code[i] == '\\' and i + 1 < n:
                    # Skip escaped character
                    i += 2
                elif code[i] == '"':
                    # End of string
                    i += 1
                    break
                else:
                    i += 1
            continue

        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()

        i += 1

    return len(stack) == 0
