function longestCommonPrefix(strs) {
  if (!Array.isArray(strs)) {
    throw new TypeError('Argument must be an array');
  }
  for (const s of strs) {
    if (typeof s !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  if (strs.length === 0) return '';
  if (strs.length === 1) return strs[0];

  const minLen = Math.min(...strs.map(s => s.length));
  if (minLen === 0) return '';

  const first = strs[0];
  let i = 0;
  while (i < minLen) {
    const code = first.charCodeAt(i);
    if (code >= 0xD800 && code <= 0xDBFF) {
      // Start of a surrogate pair
      if (i + 1 >= minLen || first.charCodeAt(i + 1) < 0xDC00 || first.charCodeAt(i + 1) > 0xDFFF) {
        return first.slice(0, i);
      }
      i += 2;
      continue;
    }
    if (code >= 0xDC00 && code <= 0xDFFF) {
      // Orphan trailing surrogate
      return first.slice(0, i);
    }
    for (let j = 1; j < strs.length; j++) {
      const other = strs[j];
      if (i >= other.length || other.charCodeAt(i) !== code) {
        return first.slice(0, i);
      }
    }
    i++;
  }
  return first.slice(0, i);
}

