        raise ValueError("date_str must be a valid date")

    # Calculate new year and month
    new_year = year + (month + n - 1) // 12
    new_month = (month + n - 1) % 12 + 1

    # Determine the last day of the target month
    try:
        # Create a date with the same day to check if it's valid
        last_day = datetime.date(new_year, new_month, 28).month + 1
        # Find the actual last day of the month
        if new_month == 12:
            next_month = datetime.date(new_year + 1, 1, 1)
        else:
            next_month = datetime.date(new_year, new_month + 1, 1)
        last_day = (next_month - datetime.date(new_year, new_month, 1)).days + 1
    except:
        raise ValueError("Invalid date calculation")

    # Clamp day if necessary
    if day > last_day:
        day = last_day

    # Check if the resulting date is within valid range
    try:
        result = datetime.date(new_year, new_month, day)
    except ValueError:
        raise ValueError("Resulting date is invalid")

    if not (1 <= result.year <= 9999):
        raise ValueError("Resulting year is outside valid range")

    return result.isoformat()

def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate input and sort by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # Check if intervals overlap or touch
        if current_start <= last_end:
            # Merge intervals by extending the end of the last interval
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # No overlap, add the current interval to the result
            merged.append([current_start, current_end])

    return merged

