def maze_steps(grid):
    if not grid:
        raise ValueError("Grid cannot be empty")

    rows = len(grid)
    cols = len(grid[0])

    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")
        for char in row:
            if char not in 'S.E#':
                raise ValueError(f"Invalid character: {char}")

    start = None
    end = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                if start is not None:
                    raise ValueError("Multiple start positions found")
                start = (r, c)
            elif grid[r][c] == 'E':
                if end is not None:
                    raise ValueError("Multiple end positions found")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one start and one end position required")

    if start == end:
        return 0

    queue = [start]
    visited = {start}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    steps = 0

    while queue:
        next_queue = []
        for r, c in queue:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                    if (nr, nc) == end:
                        return steps + 1
                    visited.add((nr, nc))
                    next_queue.append((nr, nc))
        queue = next_queue
        steps += 1

    return -1
